package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string           // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string          // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsWrapTotal decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsSafeTotal decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsOverflows int64          // PIC 99 len=2 = 0
var WsCount int64              // PIC 99 len=2 = 0
var WsHalf decimal.Decimal    // PIC 9(5)V9 len=6 = 0
var WsAmtEd string             // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string            // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string            // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string            // PIC ZZ,ZZ9.9 len=8

var curRec AmtRec
var amtFile *os.File
var amtScanner *bufio.Scanner
var amtEOF bool

func inputDone() bool {
	return WsEofFlag == "Y"
}

func parseAmtField(s string) decimal.Decimal {
	// s length 7, digits only, implied V99
	// non-digits (spaces) treated as zero
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	// if shorter, already padded; if longer, only first len used by caller
	return decimal.New(n, -2)
}

func fitPic(v decimal.Decimal, intDigits int32, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	shifted := t.Shift(scale)
	cents := shifted.IntPart()
	// modulus = 10^(intDigits+scale)
	var mod int64 = 1
	for i := int32(0); i < intDigits+scale; i++ {
		mod *= 10
	}
	cents = cents % mod
	return decimal.New(cents, -scale)
}

func fit72(v decimal.Decimal) decimal.Decimal {
	return fitPic(v, 7, 2)
}
func fit52(v decimal.Decimal) decimal.Decimal {
	return fitPic(v, 5, 2)
}
func fit51(v decimal.Decimal) decimal.Decimal {
	return fitPic(v, 5, 1)
}

func formatZZZZ9_99(v decimal.Decimal) string {
	// PIC ZZ,ZZ9.99 width 9
	t := v.Truncate(2)
	cents := t.Shift(2).IntPart()
	neg := cents < 0
	if neg {
		cents = -cents
	}
	intPart := cents / 100
	frac := cents % 100
	// keep low-order 5 digits
	intPart = intPart % 100000
	d := [5]int64{}
	tmp := intPart
	for i := 4; i >= 0; i-- {
		d[i] = tmp % 10
		tmp /= 10
	}
	out := make([]byte, 9)
	// positions 0:Z(d0) 1:Z(d1) 2:, 3:Z(d2) 4:Z(d3) 5:9(d4) 6:. 7:9 8:9
	suppressed := true
	chars := make([]byte, 5)
	for i := 0; i < 5; i++ {
		isLast := (i == 4)
		if isLast {
			chars[i] = byte('0' + d[i])
		} else {
			if suppressed && d[i] == 0 {
				chars[i] = ' '
			} else {
				suppressed = false
				chars[i] = byte('0' + d[i])
			}
		}
		// if we printed non-zero, suppression ends (already)
		// Note: once suppressed==false it stays false
	}
	out[0] = chars[0]
	out[1] = chars[1]
	if suppressed {
		// still suppressed after first two digits -> comma blank
		// check: suppression flag currently reflects d0,d1 (and not yet d2..)
		// Actually suppression after processing d0,d1 only. Our loop already
		// processed all, but comma decision depends on state after d1.
		// Recompute:
		if chars[0] == ' ' && chars[1] == ' ' {
			out[2] = ' '
		} else {
			out[2] = ','
		}
	} else {
		// This branch means a later digit nonzero but first two zero?
		// Comma still blank if first two were blank.
		if chars[0] == ' ' && chars[1] == ' ' {
			out[2] = ' '
		} else {
			out[2] = ','
		}
	}
	out[3] = chars[2]
	out[4] = chars[3]
	out[5] = chars[4]
	out[6] = '.'
	out[7] = byte('0' + (frac / 10))
	out[8] = byte('0' + (frac % 10))
	_ = neg
	return string(out)
}

func formatZZZZ9_9(v decimal.Decimal) string {
	// PIC ZZ,ZZ9.9 width 8
	t := v.Truncate(1)
	tenths := t.Shift(1).IntPart()
	neg := tenths < 0
	if neg {
		tenths = -tenths
	}
	intPart := tenths / 10
	frac := tenths % 10
	intPart = intPart % 100000
	d := [5]int64{}
	tmp := intPart
	for i := 4; i >= 0; i-- {
		d[i] = tmp % 10
		tmp /= 10
	}
	out := make([]byte, 8)
	chars := make([]byte, 5)
	suppressed := true
	for i := 0; i < 5; i++ {
		isLast := (i == 4)
		if isLast {
			chars[i] = byte('0' + d[i])
		} else {
			if suppressed && d[i] == 0 {
				chars[i] = ' '
			} else {
				suppressed = false
				chars[i] = byte('0' + d[i])
			}
		}
	}
	out[0] = chars[0]
	out[1] = chars[1]
	if chars[0] == ' ' && chars[1] == ' ' {
		out[2] = ' '
	} else {
		out[2] = ','
	}
	out[3] = chars[2]
	out[4] = chars[3]
	out[5] = chars[4]
	out[6] = '.'
	out[7] = byte('0' + frac)
	_ = neg
	return string(out)
}

func formatPIC99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func READPARA() {
	if amtScanner.Scan() {
		line := amtScanner.Text()
		// strip trailing \r if present (windows)
		line = strings.TrimSuffix(line, "\r")
		// pad with spaces to 11
		if len(line) < 11 {
			line = line + strings.Repeat(" ", 11-len(line))
		} else if len(line) > 11 {
			line = line[:11]
		}
		acct := line[0:4]
		amtStr := line[4:11]
		curRec.ArAcct = acct
		curRec.ArAmt = parseAmtField(amtStr)
	} else {
		WsEofFlag = "Y"
	}
}

func OVERFLOWPARA() {
	WsOverflows = (WsOverflows + 1) % 100
}

func PROCESSPARA() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = fit72(WsBigTotal.Add(curRec.ArAmt))
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = fit52(WsBigTotal)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	sum := WsSafeTotal.Add(curRec.ArAmt)
	// size error if sum > 99999.99 i.e. >= 100000.00
	limit := decimal.New(100000, 0)
	if sum.GreaterThanOrEqual(limit) || sum.GreaterThan(decimal.New(9999999, -2)) {
		OVERFLOWPARA()
	} else {
		WsSafeTotal = fit52(sum)
	}
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100
	// COMPUTE WS-HALF = AR-AMT / 2 (truncated to 1 decimal)
	cents := curRec.ArAmt.Shift(2).IntPart()
	tenths := cents / 20 // truncates toward zero
	WsHalf = fit51(decimal.New(tenths, -1))
	// MOVEs to edited
	WsAmtEd = formatZZZZ9_99(curRec.ArAmt)
	WsWrapEd = formatZZZZ9_99(WsWrapTotal)
	WsSafeEd = formatZZZZ9_99(WsSafeTotal)
	WsHalfEd = formatZZZZ9_9(WsHalf)
	fmt.Printf("%s %s %s %s %s\n", curRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	READPARA()
}

func SUMMARYPARA() {
	fmt.Printf("RECORDS: %s\n", formatPIC99(WsCount))
	fmt.Printf("OVERFLOWS: %s\n", formatPIC99(WsOverflows))
}

func main() {
	WsEofFlag = "N"
	WsBigTotal = decimal.New(0, 0)
	WsWrapTotal = decimal.New(0, 0)
	WsSafeTotal = decimal.New(0, 0)
	WsOverflows = 0
	WsCount = 0
	WsHalf = decimal.New(0, 0)

	var err error
	amtFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	amtScanner = bufio.NewScanner(amtFile)
	// allow long lines
	// MAIN-PARA
	READPARA()
	for !inputDone() {
		PROCESSPARA()
	}
	amtFile.Close()
	SUMMARYPARA()
}
